## Submitted testbench
```systemverilog
module tb;

  // ------------------------------------------------------------
  // Parameters
  // ------------------------------------------------------------
  localparam int CLK_PERIOD = 8;               // 125 MHz clock
  localparam logic [15:0] PRESCALE_VAL = 16'h5; // non‑zero, stable prescale

  // ------------------------------------------------------------
  // Clock & Reset
  // ------------------------------------------------------------
  logic clk = 0;
  logic rst = 0;

  // ------------------------------------------------------------
  // UART / AXI signals
  // ------------------------------------------------------------
  logic rxd = 1'b1;                 // UART receive line (driven by testbench)
  logic txd;                        // UART transmit line (observed only for legality)

  // AXI‑Stream signals (top‑level uart ports)
  logic [7:0] s_axis_tdata;
  logic       s_axis_tvalid;
  logic       s_axis_tready;        // driven by DUT, not touched by TB

  logic [7:0] m_axis_tdata;         // AXI‑Stream read data from RX
  logic       m_axis_tvalid;        // AXI‑Stream read valid
  logic       m_axis_tready;        // AXI‑Stream read ready (driven by TB)

  // Status / control signals (not used by TB)
  logic tx_busy;
  logic rx_busy;
  logic rx_overrun_error;
  logic rx_frame_error;

  // Prescale value driven to the constant defined above
  logic [15:0] prescale = PRESCALE_VAL;

  // ------------------------------------------------------------
  // DUT instantiation (default parameters)
  // ------------------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk               (clk),
    .rst               (rst),
    .s_axis_tdata      (s_axis_tdata),
    .s_axis_tvalid     (s_axis_tvalid),
    .s_axis_tready     (s_axis_tready),
    .m_axis_tdata      (m_axis_tdata),
    .m_axis_tvalid     (m_axis_tvalid),
    .m_axis_tready     (m_axis_tready),
    .txd               (txd),
    .tx_busy           (tx_busy),
    .rx_busy           (rx_busy),
    .rx_overrun_error  (rx_overrun_error),
    .rx_frame_error    (rx_frame_error),
    .prescale          (prescale)
  );

  // ------------------------------------------------------------
  // Clock generation
  // ------------------------------------------------------------
  always #(CLK_PERIOD/2) clk = ~clk;

  // ------------------------------------------------------------
  // Reset sequence
  // ------------------------------------------------------------
  initial begin
    #100;
    rst = 1'b0;
    #100;
    rst = 1'b1;
    #100;
    rst = 1'b0;
    #100;
  end

  // ------------------------------------------------------------
  // Tie off unused AXI inputs
  // ------------------------------------------------------------
  initial begin
    s_axis_tdata  = 8'b0;
    s_axis_tvalid = 1'b0;
    // s_axis_tready is an output of the DUT – do not drive it.
  end

  // ------------------------------------------------------------
  // Task: send one byte over the UART line (rxd)
  // ------------------------------------------------------------
  task automatic uart_send_byte(input byte unsigned b);
    int unsigned bit_clks;
    bit_clks = int'(prescale) * 8; // one bit time

    // Start bit
    rxd = 0;
    repeat (bit_clks) @(negedge clk);

    // Data bits (LSB first)
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      repeat (bit_clks) @(negedge clk);
    end

    // Stop bit
    rxd = 1'b1;
    repeat (bit_clks) @(negedge clk);
  endtask

  // ------------------------------------------------------------
  // Flag: a 0x3C word has been received but not yet accepted
  // ------------------------------------------------------------
  logic pending_3c = 0;
  always @(posedge clk) begin
    if (rst) pending_3c <= 0;
    else if (m_axis_tvalid && !m_axis_tready && m_axis_tdata == 8'h3C)
      pending_3c <= 1'b1;
  end

  // ------------------------------------------------------------
  // Drive m_axis_tready only when a pending 0x3C word is accepted
  // together with a new 0xA5 word being presented.
  // ------------------------------------------------------------
  assign m_axis_tready = pending_3c && m_axis_tvalid && (m_axis_tdata == 8'hA5);

  // ------------------------------------------------------------
  // Detect when the above condition has been satisfied and finish
  // ------------------------------------------------------------
  logic finish_triggered = 0;
  always @(posedge clk) begin
    if (rst) finish_triggered <= 0;
    else if (m_axis_tready && !finish_triggered) finish_triggered <= 1'b1;
  end

  always @(posedge clk) begin
    if (finish_triggered) begin
      #1000; // allow a couple of cycles to propagate
      $finish;
    end
  end

  // ------------------------------------------------------------
  // Apply the stimulus sequence
  // ------------------------------------------------------------
  initial begin
    // Wait for reset release
    #200;

    // First frame: payload = 0x3C  (will be accepted later)
    uart_send_byte(8'h3C);

    // Second frame: payload = 0xA5 (should be presented while
    // pending_3c is still true, causing m_axis_tready to go high)
    uart_send_byte(8'hA5);

    // If for any reason the condition never fires, bail out after a long wait
    #50000;
    $finish;
  end

endmodule
